// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint amount, uint time) public {
        amount = bound(amount, 10 ether, 10 ether);
        vm.assume(time > block.timestamp);
        vm.warp(time);
        uint balanceBefore = address(c).balance;
        (bool success, ) = address(c).call{value: amount}("");
        vm.assume(success);
        assertTrue(c.pastBlockTime() == time);
    }
}

